pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {DEP_BANK} from "../src/DEP_BANK.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    DEP_BANK c;

    function setUp() public {
        c = new DEP_BANK();
    }

    function _run(address sender, uint256 a1, uint256 a2) internal {
        a1 = bound(a1, 0, 1000000000000000000000000000000);
        a2 = bound(a2, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP + VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= a1 + a2);
        try c.Deposit{value: a1}() {} catch { return; }
        try c.Deposit{value: a2}() {} catch { return; }
        uint256 bal;
        try c.balances(address(this)) returns (uint256 __r) { bal = __r; } catch { return; }
        assertTrue(bal >= a1 + a2);
    }

    function testFuzz_run(address sender, uint256 a1, uint256 a2) public {
        _run(sender, a1, a2);
    }

    receive() external payable { }
}
